window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-07b9a0976269db55"]={"versions": [{"id": "FIG-07b9a0976269db55", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Attributwert-Variationspunkten im AUTOSAR Generic Structure Template (GST). Es spezifiziert die Metaklassen zur Parametrisierung variabler Eigenschaftswerte über Formelausdrücke sowie die Verknüpfung zu Systemkonstanten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SwSystemconstDependentFormula</strong> (<em>FormulaExpression</em>): Abstrakte Basisklasse für formelbasierte Ausdrücke mit Abhängigkeiten zu Systemkonstanten. Sie besitzt zwei gerichtete Assoziationen zur externen Entität <code>SystemConstant::SwSystemconst</code> (<em>ARElement</em>):</li>\n<li>Rolle <code>+sysc</code> mit Multiplizität <code>1</code></li>\n<li>Rolle <code>+syscString</code> mit Multiplizität <code>1</code></li>\n<li><strong>ConditionByFormula</strong>: Spezialisiert <code>SwSystemconstDependentFormula</code> und enthält das Attribut:</li>\n<li><code>bindingTime: BindingTimeEnum</code></li>\n<li><strong>AttributeValueVariationPoint</strong>: Abstrakte Basisklasse, spezialisiert <code>SwSystemconstDependentFormula</code>. Definiert gemeinsame Variationspunkt-Attribute:</li>\n<li><code>bindingTime: BindingTimeEnum [0..1]</code></li>\n<li><code>blueprintValue: String [0..1]</code></li>\n<li><code>sd: String [0..1]</code></li>\n<li><code>shortLabel: Identifier [0..1]</code></li>\n<li>Spezifische Subklassen von <code>AttributeValueVariationPoint</code>:</li>\n<li><code>IntegerValueVariationPoint</code></li>\n<li><code>FloatValueVariationPoint</code></li>\n<li><code>PositiveIntegerValueVariationPoint</code></li>\n<li><code>BooleanValueVariationPoint</code></li>\n<li><code>UnlimitedIntegerValueVariationPoint</code></li>\n<li><code>AbstractNumericalVariationPoint</code> (abstrakt)</li>\n<li>Subklassen von <code>AbstractNumericalVariationPoint</code>:</li>\n<li><code>NumericalValueVariationPoint</code></li>\n<li><code>LocalConstraints::Limit</code> (externer Typ mit Attribut <code>intervalType: IntervalTypeEnum [0..1]</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Zur Konfigurations- oder Bindezeit (<code>bindingTime</code>) werden die definierten Formeln unter Auswertung der referenzierten Systemkonstanten (<code>sysc</code>, <code>syscString</code>) zu konkreten Attributwerten aufgelöst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassenhierarchie stellt sicher, dass typisierte skalare Modellattribute (Ganzzahlen, Fließkommazahlen, Wahrheitswerte, Grenzwerte) im Baukastensystem einheitlich mit Bindungszeiten, Blueprint-Vorgaben und Formelbedingungen versehen werden können. Die Kardinalität <code>1</code> der Systemkonstanten-Rollen erfordert jeweils eine gültige Referenzierung im Modell.</p>"}, {"id": "FIG-48bb16e924a2a22d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Attributwert-Variationspunkten im AUTOSAR Generic Structure Template (GST). Es spezifiziert die Metaklassen zur Parametrisierung variabler Eigenschaftswerte über Formelausdrücke sowie die Verknüpfung zu Systemkonstanten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SwSystemconstDependentFormula</strong> (<em>FormulaExpression</em>): Abstrakte Basisklasse für formelbasierte Ausdrücke mit Abhängigkeiten zu Systemkonstanten. Sie besitzt zwei gerichtete Assoziationen zu <code>SwSystemconst</code> (<em>ARElement</em>, <em>AtpDefinition</em>):</li>\n<li>Rolle <code>+sysc</code> mit Multiplizität <code>1</code></li>\n<li>Rolle <code>+syscString</code> mit Multiplizität <code>1</code></li>\n<li><strong>ConditionByFormula</strong>: Spezialisiert <code>SwSystemconstDependentFormula</code> und enthält das Attribut:</li>\n<li><code>bindingTime :BindingTimeEnum</code></li>\n<li><strong>AttributeValueVariationPoint</strong>: Abstrakte Basisklasse, spezialisiert <code>SwSystemconstDependentFormula</code>. Definiert Attribute:</li>\n<li><code>bindingTime :BindingTimeEnum [0..1]</code></li>\n<li><code>blueprintValue :String [0..1]</code></li>\n<li><code>sd :String [0..1]</code></li>\n<li><code>shortLabel :PrimitiveIdentifier [0..1]</code></li>\n<li>Spezifische Subklassen von <code>AttributeValueVariationPoint</code>:</li>\n<li><code>IntegerValueVariationPoint</code></li>\n<li><code>FloatValueVariationPoint</code></li>\n<li><code>PositiveIntegerValueVariationPoint</code></li>\n<li><code>BooleanValueVariationPoint</code></li>\n<li><code>UnlimitedIntegerValueVariationPoint</code></li>\n<li><code>AbstractNumericalVariationPoint</code> (abstrakt)</li>\n<li>Subklassen von <code>AbstractNumericalVariationPoint</code>:</li>\n<li><code>NumericalValueVariationPoint</code></li>\n<li><code>LimitValueVariationPoint</code> mit Attribut:</li>\n<li><code>intervalType :IntervalTypeEnum [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Zur Konfigurations- oder Bindezeit (<code>bindingTime</code>) werden die definierten Formeln unter Auswertung der referenzierten Systemkonstanten (<code>sysc</code>, <code>syscString</code>) zu konkreten Attributwerten aufgelöst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassenhierarchie stellt sicher, dass typisierte skalare Modellattribute (Ganzzahlen, Fließkommazahlen, Wahrheitswerte, Grenzwerte) einheitlich mit Bindungszeiten, Blueprint-Vorgaben und Formelbedingungen versehen werden können. Das Attribut <code>shortLabel</code> ist als <code>PrimitiveIdentifier</code> typisiert. Die Kardinalität <code>1</code> der Systemkonstanten-Rollen erfordert jeweils eine gültige Referenzierung von <code>SwSystemconst</code>.</p>"}], "trans": [{"from": "FIG-07b9a0976269db55", "to": "FIG-48bb16e924a2a22d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>AttributeValueVariationPoint</strong>: Der Typ des Attributs <code>shortLabel</code> ändert sich von <code>Identifier [0..1]</code> zu <code>PrimitiveIdentifier [0..1]</code>.</li>\n<li><strong>SystemConstant::SwSystemconst</strong>: Die Entität wird als <code>SwSystemconst</code> referenziert; oben rechts wird neben <code>ARElement</code> der zusätzliche Typ- bzw. Stereotypvermerk <code>AtpDefinition</code> aufgeführt.</li>\n<li><strong>LocalConstraints::Limit / LimitValueVariationPoint</strong>: Die Klasse <code>LocalConstraints::Limit</code> (grün hinterlegt) wird durch die Klasse <code>LimitValueVariationPoint</code> (gelb/beige hinterlegt) ersetzt.</li>\n</ul>"}]};
